-- Gold Query
SELECT t2.long_passing FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id ORDER BY t1.birthday ASC, t1.id NULLS LAST, t2.id NULLS LAST LIMIT 1;

