SELECT Player_Attributes.long_passing FROM Player_Attributes INNER JOIN Player ON Player_Attributes.player_api_id = Player.player_api_id ORDER BY Player.birthday DESC, Player_Attributes.id NULLS LAST, Player.id NULLS LAST LIMIT 1;

